#!/usr/bin/env python3
"""Generate a catalog of the public component classes for the showcase."""

from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT.parent / "lib" / "src"
OUT = ROOT / "lib" / "catalog.dart"

entries: list[tuple[str, str]] = []
for path in sorted(SRC.glob("*.dart")):
    match = re.search(r"class\s+(\w+)\s+extends\s+StatelessComponent", path.read_text())
    if match:
        entries.append((match.group(1), path.name))

lines = [
    "// Generated by tool/generate_catalog.py; do not edit by hand.",
    "",
    "class ComponentEntry {",
    "  final String name;",
    "  final String file;",
    "",
    "  const ComponentEntry(this.name, this.file);",
    "}",
    "",
    "const List<ComponentEntry> allComponents = [",
]
for name, file in entries:
    lines.append(f"  ComponentEntry('{name}', '{file}'),")
lines.append("];")
OUT.write_text("\n".join(lines) + "\n")
print(f"Generated {len(entries)} component entries at {OUT}")
